mapper.select:
select  from dating_service_option
status = #{status}
order by option_id

select  from dating_service_option where code in
#{code}
order by option_id

select id as user_id, name, phone, status, create_by, service_status, as effective_owner from sys_paying_user u where del_flag = '0' and = #{owner}
and (name like concat('%', #{keyword}, '%') or phone like concat('%', #{keyword}, '%'))
order by id desc

select  

    and  = #{owner}
    and o.order_no like concat('%', #{orderNo}, '%')
    and o.status = #{status}
    and o.user_id = #{userId}

order by o.order_id desc

select e.*, o.order_no, o.package_name, u.name as user_name
from dating_entitlement e join dating_order o on o.order_id = e.order_id
join sys_paying_user u on u.id = e.user_id

    and e.user_id = #{userId}
    and  = #{owner}

order by e.entitlement_id desc

select e.*,o.order_no,o.package_name,u.name as user_name
from dating_entitlement e join dating_order o on o.order_id=e.order_id
join sys_paying_user u on u.id=e.user_id
where e.entitlement_id=#{id}
and  = #{owner}
